import React from 'react';

/** Visual variant for the Badge. */
export type BadgeVariant = 'solid' | 'dither' | 'outline' | 'ghost' | 'inverted' | 'pixel';

/** Semantic color for the Badge. */
export type BadgeColor = 'success' | 'warning' | 'destructive' | 'info';

/** Props for the {@link Badge} component. */
export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Visual variant. */
  variant?: BadgeVariant;
  /** Semantic color override. */
  color?: BadgeColor;
  /** Animate with a pulsing effect. */
  pulsing?: boolean;
  /** Additional CSS class names. */
  className?: string;
  children?: React.ReactNode;
}

/**
 * Status indicator with dither fill.
 * Renders a `<span>` with the `sk-badge` class.
 */
export const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  ({ variant, color, pulsing, className, children, ...rest }, ref) => (
    <span
      ref={ref}
      className={`sk-badge${className ? ` ${className}` : ''}`}
      data-variant={variant}
      data-color={color}
      data-pulsing={pulsing ? '' : undefined}
      {...rest}
    >
      {children}
    </span>
  ),
);

Badge.displayName = 'Badge';

/**
 * skeehn — Badge Component
 *
 * @component sk-badge
 * @variants  solid | dither | outline | ghost | inverted | pixel | retro | ascii
 * @colors    success | warning | destructive | info
 * @states    [data-pulsing] | [data-loading] | [data-skeleton]
 * @a11y      Inline-flex for alignment, color not sole indicator
 * @print     Text-only with border
 */
.sk-badge {
  display: inline-flex;
  align-items: center;
  /* slightly more substantial than before: taller line-height, snugger h-padding */
  padding: var(--sk-space-1) var(--sk-space-2);
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: var(--sk-letter-spacing-wide);
  text-transform: uppercase;
  border-radius: var(--sk-radius);
  border: 1px solid transparent;
  white-space: nowrap;
  position: relative;
  overflow: hidden;
}
.sk-badge:focus-visible { outline: var(--sk-focus-ring); outline-offset: 2px; }

/* Solid */
.sk-badge[data-variant="solid"] { background: hsl(var(--sk-secondary)); }

/* Dither — badge face gets --sk-dither-b6 at 15% opacity via ::before */
.sk-badge[data-variant="dither"] {
  background: hsl(var(--sk-secondary));
  position: relative;
  overflow: hidden;
}
.sk-badge[data-variant="dither"]::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-b6, var(--sk-dither-pattern));
  background-repeat: repeat;
  opacity: 0.15;
  pointer-events: none;
  mix-blend-mode: overlay;
}

/* Outline */
.sk-badge[data-variant="outline"] { background: transparent; border-color: hsl(var(--sk-border-color)); }

/* Ghost */
.sk-badge[data-variant="ghost"] { background: hsl(var(--sk-accent)); }

/* Inverted */
.sk-badge[data-variant="inverted"] { background: hsl(var(--sk-foreground)); color: hsl(var(--sk-background)); }

/* Pixel — solid fill with 2px offset hard shadow */
.sk-badge[data-variant="pixel"] {
  background: hsl(var(--sk-background));
  color: hsl(var(--sk-foreground));
  border: 1px solid hsl(var(--sk-foreground));
  box-shadow: 2px 2px 0 hsl(var(--sk-foreground));
  /* small visual offset to keep shadow in frame */
  transform: translate(0, 0);
  transition: box-shadow var(--sk-transition), transform var(--sk-transition);
}
.sk-badge[data-variant="pixel"]:hover {
  box-shadow: 1px 1px 0 hsl(var(--sk-foreground));
  transform: translate(1px, 1px);
}

/* Color semantic variants */
.sk-badge[data-color="success"]     { background: hsl(var(--sk-success)     / 0.12); color: hsl(var(--sk-success)); }
.sk-badge[data-color="warning"]     { background: hsl(var(--sk-warning)     / 0.12); color: hsl(var(--sk-warning)); }
.sk-badge[data-color="destructive"] { background: hsl(var(--sk-destructive) / 0.12); color: hsl(var(--sk-destructive)); }
.sk-badge[data-color="info"]        { background: hsl(var(--sk-info)        / 0.12); color: hsl(var(--sk-info)); }

/* Pulsing state — soft pulse animation */
.sk-badge[data-pulsing] {
  animation: sk-pulse 2s ease-in-out infinite;
}

/* Retro variant — CRT glow */
.sk-badge[data-variant="retro"] {
  background: hsl(var(--sk-primary));
  color: hsl(var(--sk-background));
  border: 1px solid hsl(var(--sk-primary));
  text-shadow: 0 0 3px hsl(var(--sk-primary) / 0.5);
  box-shadow: 0 0 4px hsl(var(--sk-primary) / 0.15);
}

/* ASCII variant */
.sk-badge[data-variant="ascii"] {
  background: transparent;
  border: none;
  color: hsl(var(--sk-foreground));
}
.sk-badge[data-variant="ascii"]::before {
  content: "[";
  opacity: 0.5;
}
.sk-badge[data-variant="ascii"]::after {
  content: "]";
  opacity: 0.5;
}

/* Loading state */
@keyframes sk-badge-load {
  0%   { background-image: var(--sk-dither-b2); }
  50%  { background-image: var(--sk-dither-b8); }
  100% { background-image: var(--sk-dither-b2); }
}

.sk-badge[data-loading] {
  pointer-events: none;
  position: relative;
}
.sk-badge[data-loading]::after {
  content: "";
  position: absolute;
  inset: 0;
  background-repeat: repeat;
  animation: sk-badge-load 1.2s steps(4) infinite;
  opacity: 0.1;
  pointer-events: none;
  border-radius: inherit;
}

/* Skeleton state */
@keyframes sk-badge-shimmer {
  0%   { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

.sk-badge[data-skeleton] {
  pointer-events: none;
  color: transparent;
  background:
    linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-badge-shimmer 1.8s ease-in-out infinite;
  border-color: transparent;
}

/* Print */
@media print {
  .sk-badge {
    box-shadow: none;
    text-shadow: none;
    border: 1px solid currentColor;
    background: transparent;
  }
  .sk-badge::before, .sk-badge::after { display: none; }
  .sk-badge[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-badge[data-pulsing] { animation: none; }
  .sk-badge[data-skeleton] { animation: none; background: hsl(var(--sk-muted)); }
  .sk-badge[data-loading]::after { animation: none; }
}
